INSERT INTO `settings` VALUES ('ip_allowlist_cidrs','[\"192.168.0.0/16\",\"10.0.0.0/8\"]',NULL,NULL),('ip_allowlist_enabled','0',NULL,NULL),('login_lockout_minutes','15',NULL,NULL),('login_max_attempts','5',NULL,NULL),('max_upload_mb','25',NULL,NULL),('plagiarism_block_percent','10',NULL,NULL),('session_timeout_minutes','30',NULL,NULL);
