DROP TABLE IF EXISTS `studies`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `studies` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `submitter_user_id` int(10) unsigned NOT NULL,
  `title` varchar(512) NOT NULL,
  `short_title` varchar(80) NOT NULL,
  `abstract` text NOT NULL,
  `research_objectives` text NOT NULL,
  `study_type` enum('proposal','final_defense','thesis','dissertation','capstone','research_article','research_paper') NOT NULL,
  `program_id` smallint(5) unsigned NOT NULL,
  `adviser_user_id` int(10) unsigned DEFAULT NULL,
  `pass_to` enum('teacher','library') NOT NULL DEFAULT 'teacher',
  `school_year` varchar(9) NOT NULL,
  `defense_date` date DEFAULT NULL,
  `coi_statement` text NOT NULL,
  `status` enum('draft','submitted','adviser_reviewed','pending','dean_review','ethics_review','under_review','library_review','admin_review','revision_requested','resubmitted','approved','archived') NOT NULL DEFAULT 'draft',
  `double_blind` tinyint(1) NOT NULL DEFAULT 0,
  `current_version_id` int(10) unsigned DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `library_accepted_at` datetime DEFAULT NULL,
  `library_retracted_at` datetime DEFAULT NULL,
  `congress_status` enum('none','pending','approved','rejected') NOT NULL DEFAULT 'none',
  `archived_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_studies_status` (`status`),
  KEY `idx_studies_program` (`program_id`),
  KEY `idx_studies_submitter` (`submitter_user_id`),
  KEY `idx_studies_adviser` (`adviser_user_id`),
  KEY `fk_studies_current_version` (`current_version_id`),
  FULLTEXT KEY `ft_studies_search` (`title`,`short_title`,`abstract`,`research_objectives`),
  CONSTRAINT `fk_studies_adviser` FOREIGN KEY (`adviser_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_studies_current_version` FOREIGN KEY (`current_version_id`) REFERENCES `study_versions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_studies_program` FOREIGN KEY (`program_id`) REFERENCES `programs` (`id`),
  CONSTRAINT `fk_studies_submitter` FOREIGN KEY (`submitter_user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `studies` WRITE;
/*!40000 ALTER TABLE `studies` DISABLE KEYS */;
INSERT INTO `studies` VALUES (1,3,'thesis repository','thesis','Metadata Quality and Interoperability\r\nMetadata plays a crucial role in making digital objects in institutional repositories discoverable, accessible, and interoperable. Thoth Open Metadata (2026) provides international metadata recommendations specifically for open access repositories, emphasizing the use of persistent identifiers (DOIs, ORCID) and standardized schemas such as Dublin Core. These recommendations are directly applicable to the LSSTI repository, as they guide the selection of metadata fields that will maximize discoverability.','','thesis',3,2,'teacher','2026-2027',NULL,'','approved',0,2,'2026-10-05 01:03:12','2026-10-05 01:33:23',NULL,NULL,'none',NULL,'2026-10-05 01:03:12','2026-10-05 01:33:23'),(2,5,'test1','test1','testtesttest','','thesis',3,2,'teacher','2025-2026',NULL,'','approved',0,3,'2026-10-05 01:48:55','2026-10-05 01:52:39','2026-10-05 07:19:33',NULL,'none',NULL,'2026-10-05 01:48:55','2026-10-05 07:19:33'),(3,3,'lssti repository','LSSTI','ABSTRACT \r\nThis study focuses on the development of the Lanao School of Science and Technology Digital Research Repository, a web-based Institutional Repository System designed to centralize, organize, preserve, and provide efficient access to the institution’s scholarly works. The study addresses the challenges associated with the decentralized management of theses, capstone projects, faculty research, and other academic materials, including difficulty in searching and retrieving documents, limited accessibility, delays in submission and cataloging, and risks of record loss and inconsistency. The system provides features for document submission, metadata management, review and approval, search and retrieval, access control, digital preservation, and reporting. The study employs an evaluation process involving students, faculty members, researchers, library personnel, and administrators using a structured questionnaire and a five-point Likert scale to assess the system’s functionality, usability, reliability, and efficiency. The proposed system aims to provide LSSTI with a centralized and organized digital repository that improves the accessibility, preservation, and management of its scholarly works while supporting efficient repository administration and future research.\r\nKeywords: Institutional Repository, Digital Research Repository, Digital Preservation, Metadata Management, Scholarly Works, LSSTI','','thesis',3,2,'teacher','2026-2027',NULL,'','approved',0,4,'2026-10-05 05:30:10','2026-10-05 05:40:11','2026-10-05 07:18:59',NULL,'none',NULL,'2026-10-05 05:30:09','2026-10-05 07:18:59'),(4,6,'The effect of lssti','lssti effect','This study focuses on the development of the Lanao School of Science and Technology Digital Research Repository, a web-based Institutional Repository System designed to centralize, organize, preserve, and provide efficient access to the institution’s scholarly works. The study addresses the challenges associated with the decentralized management of theses, capstone projects, faculty research, and other academic materials, including difficulty in searching and retrieving documents, limited accessibility, delays in submission and cataloging, and risks of record loss and inconsistency. The system provides features for document submission, metadata management, review and approval, search and retrieval, access control, digital preservation, and reporting. The study employs an evaluation process involving students, faculty members, researchers, library personnel, and administrators using a structured questionnaire and a five-point Likert scale to assess the system’s functionality, usability, reliability, and efficiency. The proposed system aims to provide LSSTI with a centralized and organized digital repository that improves the accessibility, preservation, and management of its scholarly works while supporting efficient repository administration and future research.\r\nKeywords: Institutional Repository, Digital Research Repository, Digital Preservation, Metadata Management, Scholarly Works, LSSTI','','capstone',1,5,'teacher','2025-2026',NULL,'','approved',0,5,'2026-10-05 07:09:15','2026-10-05 07:24:40','2026-10-07 01:55:26',NULL,'none',NULL,'2026-10-05 07:09:15','2026-10-07 01:55:26'),(5,3,'lssti repository 2','lssti','kakakakakkakakakakkakkakakaka','','thesis',3,2,'teacher','2025-2026',NULL,'','approved',0,6,'2026-10-05 08:15:45','2026-10-05 08:21:56',NULL,NULL,'none',NULL,'2026-10-05 08:15:45','2026-10-05 08:21:56'),(6,3,'wewe','thesis','wewe','','thesis',3,2,'teacher','2024-2025',NULL,'','approved',0,7,'2026-10-07 02:05:22','2026-10-07 02:14:45',NULL,NULL,'none',NULL,'2026-10-07 02:05:22','2026-10-07 02:14:45'),(7,3,'sample','sample','sample','','thesis',3,2,'teacher','2026-2027',NULL,'','admin_review',0,8,'2026-10-15 03:21:57',NULL,NULL,NULL,'none',NULL,'2026-10-15 03:21:57','2026-10-16 14:58:04');
